import{_ as o,o as l,c as a,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Rook Ceph Disaster Recovery","description":"","frontmatter":{"title":"Rook Ceph Disaster Recovery","date":"2026-04-02T00:00:00.000Z","updated":"2026-04-03T00:00:00.000Z","tags":["Ceph","disaster recovery","Kubernetes","Rook","OSD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Rook_Ceph_Disaster_Recovery.md","filePath":"posts/2026/Rook_Ceph_Disaster_Recovery.md","lastUpdated":1780459816000}'),t={name:"posts/2026/Rook_Ceph_Disaster_Recovery.md"};function r(s,e,n,d,c,p){return l(),a("div",null,[...e[0]||(e[0]=[i('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本文整理自 Dinakaran（NPCA 公司 MLOps 工程师）的技术分享，主题为在 Kubernetes 集群中运行 Rook Ceph 时的灾难恢复策略。演讲涵盖了生产环境中常见的四类故障场景，并通过实操演示展示了如何在完全销毁集群后实现无数据丢失的恢复。</p><h2 id="场景一-mon-仲裁恢复-recovering-mon-quorum" tabindex="-1">场景一：MON 仲裁恢复（Recovering MON Quorum） <a class="header-anchor" href="#场景一-mon-仲裁恢复-recovering-mon-quorum" aria-label="Permalink to &quot;场景一：MON 仲裁恢复（Recovering MON Quorum）&quot;">​</a></h2><p>MON 仲裁丢失是 Ceph 集群中最常见的故障之一，通常由节点突然重启导致。</p><p><strong>恢复步骤：</strong></p><ol><li>使用 <code>kubectl get pods</code> 检查 MON Pod 状态，确认哪些 MON 处于 <code>CrashLoopBackOff</code> 状态。</li><li>删除异常的 MON Pod，Rook operator 会自动重新调度。</li><li>若 MON 无法自动恢复，可通过手动命令强制添加 MON，使集群重新达到 quorum。</li></ol><p><strong>关键点：</strong> 只要有一个健康的 MON（如 mon-B），集群就具备恢复基础，通过重启或手动添加 mon-A、mon-C 即可恢复仲裁。</p><h2 id="场景二-osd-故障处理-osd-failure" tabindex="-1">场景二：OSD 故障处理（OSD Failure） <a class="header-anchor" href="#场景二-osd-故障处理-osd-failure" aria-label="Permalink to &quot;场景二：OSD 故障处理（OSD Failure）&quot;">​</a></h2><p>OSD 故障通常由硬盘损坏或其他硬件问题引起。</p><p><strong>恢复步骤：</strong></p><ol><li>执行 <code>ceph status</code> 确认哪些 OSD 处于 down 状态。</li><li>将故障 OSD 标记为 out：<code>ceph osd out &lt;osd-id&gt;</code>。</li><li>将对应 Deployment 的副本数缩减为 0，停止该 OSD 进程。</li><li>进入 toolbox Pod，执行 <code>ceph osd safe-to-destroy &lt;osd-id&gt;</code> 确认可以安全销毁。</li><li>执行 <code>ceph osd purge &lt;osd-id&gt;</code> 从集群中彻底移除该 OSD。</li><li><strong>关键步骤（不可遗漏）：</strong> 执行 <code>ceph osd tree</code> 确认该 OSD 已从 CRUSH map 中移除，否则后续添加新 OSD 时会遇到冲突问题。</li><li>删除对应的 Deployment，完成清理。</li><li>若磁盘可复用（非损坏/丢失），需执行磁盘清理操作后方可重新加入集群。</li></ol><h2 id="场景三-节点故障与替换-node-failure-replacement" tabindex="-1">场景三：节点故障与替换（Node Failure / Replacement） <a class="header-anchor" href="#场景三-节点故障与替换-node-failure-replacement" aria-label="Permalink to &quot;场景三：节点故障与替换（Node Failure / Replacement）&quot;">​</a></h2><p>以 10 节点集群为例，当某个节点完全宕机时的处理流程：</p><p><strong>恢复步骤：</strong></p><ol><li>查找该节点上所有 OSD 的 ID。</li><li>按照场景二的流程，逐一对每个 OSD 执行 mark out → purge → 从 CRUSH map 移除的操作。</li><li>所有 OSD 清理完毕后，对该节点执行 <code>kubectl drain</code> 驱逐工作负载。</li><li>执行 <code>kubectl delete node</code> 将节点从集群中移除。</li><li>新节点加入集群后，Rook 会自动发现并纳管新磁盘，重新加入 OSD。</li></ol><h2 id="场景四-pg-不一致修复-pg-inconsistent" tabindex="-1">场景四：PG 不一致修复（PG Inconsistent） <a class="header-anchor" href="#场景四-pg-不一致修复-pg-inconsistent" aria-label="Permalink to &quot;场景四：PG 不一致修复（PG Inconsistent）&quot;">​</a></h2><p>由于网络抖动或其他异常，PG 可能出现 degraded 或 inconsistent 状态。</p><p><strong>恢复步骤：</strong></p><ol><li>执行 <code>ceph status</code> 发现 PG 异常提示。</li><li>执行 <code>ceph health detail</code> 获取具体受影响的 PG ID。</li><li>针对该 PG 执行修复命令：<code>ceph pg repair &lt;pg-id&gt;</code>，确保各副本数据一致。</li><li>执行 <code>ceph pg deep-scrub &lt;pg-id&gt;</code> 进行深度扫描，检测并修复数据损坏。</li></ol><h2 id="实操演示-完整集群销毁与恢复-full-cluster-restore-demo" tabindex="-1">实操演示：完整集群销毁与恢复（Full Cluster Restore Demo） <a class="header-anchor" href="#实操演示-完整集群销毁与恢复-full-cluster-restore-demo" aria-label="Permalink to &quot;实操演示：完整集群销毁与恢复（Full Cluster Restore Demo）&quot;">​</a></h2><p>演讲者通过现场演示，展示了在 Kubernetes 上完全删除 Rook Ceph 集群后，如何实现无数据丢失的恢复。</p><h3 id="演示环境准备" tabindex="-1">演示环境准备 <a class="header-anchor" href="#演示环境准备" aria-label="Permalink to &quot;演示环境准备&quot;">​</a></h3><ul><li>部署 Rook Ceph 集群，确认所有组件（OSD、MON、CSI、operator）正常运行。</li><li>部署一个测试应用，该应用通过 RBD 存储数据库，每秒写入一条递增数字记录。</li><li>应用获取外部 IP 后开始持续写入，最后写入数字为 <strong>18</strong>。</li></ul><h3 id="集群销毁过程" tabindex="-1">集群销毁过程 <a class="header-anchor" href="#集群销毁过程" aria-label="Permalink to &quot;集群销毁过程&quot;">​</a></h3><ol><li>直接 <code>kubectl delete namespace rook-ceph</code> 无法完全删除，因为 Rook 使用 finalizers 保护关键资源。</li><li><strong>关键操作：</strong> 在删除前，必须备份以下资源： <ul><li>MON 的 ConfigMap（包含 MON endpoints、集群 FSID 等元数据）</li><li>MON 的 Secret（包含认证密钥）</li></ul></li><li>手动移除各资源的 finalizers，依次处理：ConfigMap、Secret、CephBlockPool、CSI 相关 Profile 等。</li><li>强制删除 namespace，确认 <code>rook-ceph</code> namespace 完全消失。</li></ol><h3 id="集群恢复过程" tabindex="-1">集群恢复过程 <a class="header-anchor" href="#集群恢复过程" aria-label="Permalink to &quot;集群恢复过程&quot;">​</a></h3><ol><li>重新应用 CRD（Custom Resource Definition），已存在的 CRD 会跳过，缺失的会重新创建。</li><li>重新部署 Rook operator。</li><li><strong>核心步骤：</strong> 将之前备份的 ConfigMap 和 Secret 重新应用到集群中。Rook operator 会读取旧的 MON IP 和元数据，从而识别并重建原有集群，而非创建新集群。</li><li>重新应用 cluster.yaml，重启 operator。</li><li>观察集群状态，operator 会自动拉起所有 MON 和 OSD，恢复原有集群状态。</li></ol><h3 id="恢复验证" tabindex="-1">恢复验证 <a class="header-anchor" href="#恢复验证" aria-label="Permalink to &quot;恢复验证&quot;">​</a></h3><ul><li>集群恢复后，测试应用自动重新连接并继续写入，数字从 <strong>27</strong> 开始（18 之后因集群重建耗时约 9 秒）。</li><li>进入 toolbox Pod 执行 <code>ceph status</code>，对比恢复前后的 <strong>FSID（Cluster ID）</strong> 完全一致，证明恢复的是原有集群，数据完整无损。</li></ul><h2 id="关键结论" tabindex="-1">关键结论 <a class="header-anchor" href="#关键结论" aria-label="Permalink to &quot;关键结论&quot;">​</a></h2><ul><li>Rook Ceph 的 finalizers 机制是保护集群元数据的重要手段，灾难恢复的核心在于<strong>提前备份 MON ConfigMap 和 Secret</strong>。</li><li>只要 MON 的元数据（endpoints、FSID、认证信息）完整保留，即使集群被完全删除，也可以实现无数据丢失的完整恢复。</li><li>OSD 故障处理中，从 CRUSH map 移除是容易被遗漏但至关重要的步骤。</li><li>PG inconsistent 问题通过 <code>repair</code> 和 <code>deep-scrub</code> 组合命令可有效解决。</li></ul>',31)])])}const g=o(t,[["render",r]]);export{u as __pageData,g as default};
